#!/usr/bin/env python3
import codecs
import csv
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import ROUND_HALF_UP, Decimal
from fractions import Fraction

UNIT_KG = {
    "kg": Fraction(1),
    "g": Fraction(1, 1000),
    "lb": Fraction(45359237, 100000000),
    "oz": Fraction(28349523125, 1000000000000),
}
HANDOVER_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
}
DELIMS = {"east": ",", "harbor": "|", "lakeside": ",", "river": "\t", "west": ";"}
FIELD_ALIASES = {
    "east": {"id": "id", "type": "type", "shipped": "shipped", "gross": "weight", "status": "status"},
    "harbor": {"rec": "type", "ref": "id", "date": "shipped", "weight": "weight", "state": "status"},
    "lakeside": {"id": "id", "kind": "type", "shipped": "shipped", "status": "status"},
    "river": {"t": "type", "ref": "id", "shipped": "shipped", "weight": "weight", "status": "status"},
    "west": {"id": "id", "typ": "type", "shipped": "shipped", "weight": "weight", "status": "status"},
}
BASE = {
    "east": {"date": "YMD", "unit": "kg"},
    "harbor": {"date": "iso", "unit": "kg"},
    "lakeside": {"date": "iso", "unit": "kg"},
    "river": {"date": "MM/DD/YYYY", "unit": "kg"},
    "west": {"date": "DD.MM.YYYY", "unit": "kg"},
}
STATUS_CODES = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}
FW_LAYOUTS = {
    "FW1": dict(length=42, type=(9, 10), id=(0, 9), shipped=(10, 17), weight=(17, 25), status=(25, 26),
                date="YYYYDDD", unit="g", scale=Fraction(1)),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27),
                date="YYYYMMDD", unit="kg", scale=Fraction(1, 100)),
    "FW3": dict(length=41, type=(16, 17), id=(0, 9), shipped=(9, 16), weight=(17, 24), status=(24, 25),
                date="YYYYDDD", unit="lb", scale=Fraction(1, 10)),
}


def decode_bytes(raw):
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    return raw


def decode_text(raw):
    if raw[:3] == b"\xef\xbb\xbf":
        return raw[3:].decode("utf-8", errors="replace")
    if raw[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return raw.decode("utf-16", errors="replace")
    encoding = "utf-8"
    head = raw[:4096].decode("latin-1")
    for line in head.split("\n"):
        match = re.match(r"\s*#\s*charset\s*:\s*([\w.\-]+)", line)
        if match:
            try:
                codecs.lookup(match.group(1))
                encoding = match.group(1)
            except LookupError:
                pass
            break
    return raw.decode(encoding, errors="replace")


def parse_id(text):
    match = re.fullmatch(r"\s*SH\D*(\d+)\s*", text or "", re.I)
    return int(match.group(1)) if match else None


def norm_status(text):
    return re.sub(r"[\s\-]+", "_", (text or "").strip().lower())


def norm_type(text):
    low = (text or "").strip().lower()
    if low.startswith("v"):
        return "void"
    if low.startswith(("c", "a")):
        return "correction"
    return "new"


def parse_number(text, decimal_comma):
    text = text.strip().replace(" ", "")
    if decimal_comma:
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Fraction(Decimal(text))


def parse_weight(text, unit, decimal_comma):
    text = (text or "").strip()
    match = re.fullmatch(r"(.*?)\s*(kg|g|lb|oz)", text, re.I)
    if match and match.group(1):
        text, unit = match.group(1), match.group(2).lower()
    return parse_number(text, decimal_comma) * UNIT_KG[unit]


def clean_unit(value, default):
    match = re.search(r"\b(kg|g|lb|oz)\b", (value or "").lower())
    return match.group(1) if match else default


def parse_when(value, form):
    value = (value or "").strip()
    match = re.fullmatch(
        r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d(?::?\d\d)?)?", value, re.I)
    if match:
        year, month, day, hour, minute, second, zone = match.groups()
        offset = timedelta(0)
        if zone and zone.upper() != "Z":
            digits = zone[1:].replace(":", "")
            offset = timedelta(hours=int(digits[:2]), minutes=int(digits[2:] or 0))
            if zone[0] == "-":
                offset = -offset
        moment = datetime(int(year), int(month), int(day), int(hour), int(minute), int(second or 0))
        return (moment - offset).date()
    match = re.fullmatch(r"(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})", value)
    if match:
        return date(int(match.group(3)), MONTHS[match.group(2).lower()], int(match.group(1)))
    form = (form or "").strip()
    upper = form.upper()
    if upper == "SERIAL" or (not form and re.fullmatch(r"\d{5}(\.\d+)?", value)):
        return date(1899, 12, 30) + timedelta(days=int(float(value)))
    if upper == "YYYYDDD":
        return date(int(value[:4]), 1, 1) + timedelta(days=int(value[4:7]) - 1)
    if upper == "YYYYMMDD":
        return date(int(value[:4]), int(value[4:6]), int(value[6:8]))
    parts = re.split(r"[-/.]", value)
    if len(parts) != 3:
        raise ValueError("bad date " + value)
    parts = [int(part) for part in parts]
    if upper in ("ISO", "YMD"):
        return date(parts[0], parts[1], parts[2])
    if upper in ("DMY", "DD/MM/YYYY", "DD.MM.YYYY"):
        return date(parts[2], parts[1], parts[0])
    if upper in ("MDY", "MM/DD/YYYY"):
        return date(parts[2], parts[0], parts[1])
    if parts[0] > 31:
        return date(parts[0], parts[1], parts[2])
    raise ValueError("unknown date form " + form)


def logical_lines(text, quoting):
    lines = text.split("\n")
    index = 0
    while index < len(lines):
        line = lines[index]
        index += 1
        if line.endswith("\r"):
            line = line[:-1]
        if quoting and not line.startswith("#"):
            while line.count('"') % 2 == 1 and index < len(lines):
                nxt = lines[index]
                index += 1
                line += "\n" + (nxt[:-1] if nxt.endswith("\r") else nxt)
        yield line


def split_fields(line, delim, quoting):
    if quoting:
        rows = list(csv.reader(io.StringIO(line), delimiter=delim, quotechar='"'))
        return rows[0] if rows else []
    return line.split(delim)


def header_match(depot, fields):
    names = [field.strip().lower() for field in fields]
    if not names or any(not name for name in names):
        return None
    allowed = COLUMNS[depot]
    for name in names:
        if name in allowed:
            continue
        if depot == "lakeside" and re.fullmatch(r"(gross|net)_(kg|g|lb|oz)", name):
            continue
        return None
    return names


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    quoting = delim == ","
    seq = None
    directives = {}
    header = None
    records = []
    for line in logical_lines(text, quoting):
        if not line.strip():
            continue
        if line.startswith("#"):
            match = re.match(r"#\s*([A-Za-z][\w ]*?)\s*:\s*(.*)$", line)
            if match:
                name = match.group(1).strip().lower()
                value = match.group(2).strip()
                if name == "seq":
                    if seq is None:
                        seq = int(value)
                elif name in ("dates", "date format", "date"):
                    directives["date"] = value
                elif name in ("unit", "weight unit"):
                    directives["unit"] = value
                continue
            match = re.search(r"\bseq\s*=\s*(\d+)", line)
            if match and seq is None:
                seq = int(match.group(1))
            continue
        fields = split_fields(line, delim, quoting)
        names = header_match(depot, fields)
        if names is not None:
            header = names
            continue
        if header is None:
            continue
        row = dict(zip(header, fields + [""] * (len(header) - len(fields))))
        extra = fields[len(header):]
        record = {}
        alias = FIELD_ALIASES[depot]
        for name, value in row.items():
            if name in alias:
                record[alias[name]] = value
            elif depot == "lakeside" and re.fullmatch(r"gross_(kg|g|lb|oz)", name):
                record["weight"] = value + " " + name.rsplit("_", 1)[1]
        if parse_id(record.get("id")) is None:
            continue
        unit = clean_unit(directives.get("unit"), BASE[depot]["unit"])
        for item in extra:
            if item.strip().lower() in UNIT_KG:
                unit = item.strip().lower()
        decimal_comma = depot == "west"
        records.append(dict(
            id=parse_id(record["id"]), type=norm_type(record.get("type")),
            shipped=record.get("shipped"), form=directives.get("date", BASE[depot]["date"]),
            weight=record.get("weight"), unit=unit, comma=decimal_comma,
            status=record.get("status")))
    return seq, records


def parse_south(text):
    seq = None
    layout = "FW2"
    records = []
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if not line.strip() or "\f" in line:
            continue
        if line.startswith("#LAYOUT"):
            name = line.split()[1].upper()
            if name in FW_LAYOUTS:
                layout = name
            continue
        if line.startswith("#SEQ"):
            if seq is None:
                seq = int(line.split()[1])
            continue
        if line.startswith("#") or line.upper().startswith("SOUTH DEPOT"):
            continue
        use = layout
        if len(line) != FW_LAYOUTS[layout]["length"]:
            for name, spec in FW_LAYOUTS.items():
                if spec["length"] == len(line):
                    use = name
        spec = FW_LAYOUTS[use]
        if len(line) < spec["length"]:
            line = line.ljust(spec["length"])

        def cut(key):
            return line[spec[key][0]:spec[key][1]]

        number = parse_id(cut("id").strip())
        if number is None:
            continue
        kind = norm_type(cut("type"))
        record = dict(id=number, type=kind)
        if kind != "void":
            record.update(
                shipped=cut("shipped"), form=spec["date"],
                weight=str(Fraction(int(cut("weight"))) * spec["scale"] and
                           Decimal(int(cut("weight"))) * Decimal(spec["scale"].numerator) /
                           Decimal(spec["scale"].denominator)),
                unit=spec["unit"], comma=False,
                status=STATUS_CODES.get(cut("status").strip().upper(), cut("status")))
        records.append(record)
    return seq, records


def parse_north(text):
    seq = None
    records = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            value = json.loads(line)
        except ValueError:
            continue
        items = value if isinstance(value, list) else [value]
        for item in items:
            if not isinstance(item, dict):
                continue
            if "meta" in item and isinstance(item["meta"], dict):
                if seq is None and "seq" in item["meta"]:
                    seq = int(item["meta"]["seq"])
                continue
            number = parse_id(str(item.get("id", "")))
            if number is None:
                continue
            record = dict(id=number, type=norm_type(item.get("kind")))
            if record["type"] != "void":
                weight, unit = None, "kg"
                for key, val in item.items():
                    match = re.fullmatch(r"weight(?:_(kg|g|lb|oz))?", key, re.I)
                    if match:
                        weight = str(val)
                        unit = (match.group(1) or "kg").lower()
                record.update(shipped=item.get("shipped_at"), form="iso", weight=weight,
                              unit=unit, comma=False, status=item.get("status"))
            records.append(record)
    return seq, records


def parse_central(raw):
    root = ET.fromstring(raw)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = clean_unit(root.get("weight-unit"), "kg")
    records = []
    for element in root.iter("shipment"):
        number = parse_id(element.get("id"))
        if number is None:
            continue
        record = dict(id=number, type=norm_type(element.get("type")))
        if record["type"] != "void":
            def get(name):
                child = element.find(name)
                if child is not None:
                    return (child.text or "").strip()
                return element.get(name)

            weight_node = element.find("weight")
            unit = root_unit
            if element.get("weight-unit"):
                unit = clean_unit(element.get("weight-unit"), unit)
            if weight_node is not None and weight_node.get("unit"):
                unit = clean_unit(weight_node.get("unit"), unit)
            record.update(shipped=get("shipped"), form="", weight=get("weight"), unit=unit,
                          comma=False, status=get("status"))
        records.append(record)
    return seq, records


def read_export(depot, path):
    with open(path, "rb") as handle:
        raw = decode_bytes(handle.read())
    if depot == "central":
        return parse_central(raw)
    text = decode_text(raw)
    if depot == "south":
        return parse_south(text)
    if depot == "north":
        return parse_north(text)
    if depot in DELIMS:
        return parse_delimited(depot, text)
    raise ValueError("unknown depot " + depot)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        try:
            seq, records = read_export(depot, path)
        except Exception as error:
            print("skipping %s: %s" % (name, error), file=sys.stderr)
            exports.setdefault(depot, [])
            continue
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, records))

    corrections = resends = 0
    current = {}
    for depot, items in exports.items():
        shipments = current.setdefault(depot, {})
        for _, _, records in sorted(items, key=lambda item: (item[0], item[1])):
            for record in records:
                number = record["id"]
                if record["type"] == "new":
                    if number in shipments:
                        resends += 1
                    else:
                        shipments[number] = record
                elif record["type"] == "correction":
                    shipments[number] = record
                    corrections += 1
                else:
                    shipments.pop(number, None)
                    corrections += 1

    def rank(depot):
        if depot in HANDOVER_ORDER:
            return (HANDOVER_ORDER.index(depot), depot)
        return (len(HANDOVER_ORDER), depot)

    owners = {}
    for depot in sorted(current, key=rank):
        for number in current[depot]:
            owners.setdefault(number, []).append(depot)
    handovers = sum(1 for depots in owners.values() if len(depots) > 1)

    depot_totals = {depot: [0, Fraction(0)] for depot in sorted(current)}
    month_totals = {}
    for number, depots in owners.items():
        depot = depots[0]
        record = current[depot][number]
        if norm_status(record["status"]) not in ("delivered", "delivered_late"):
            continue
        kg = parse_weight(record["weight"], record["unit"], record["comma"])
        when = parse_when(record["shipped"], record["form"])
        key = "%04d-%02d" % (when.year, when.month)
        for bucket in (depot_totals[depot], month_totals.setdefault(key, [0, Fraction(0)])):
            bucket[0] += 1
            bucket[1] += kg

    def render(bucket):
        value = Decimal(bucket[1].numerator) / Decimal(bucket[1].denominator)
        exact = (Decimal(bucket[1].numerator) * 10**30 // bucket[1].denominator)
        value = Decimal(exact) / Decimal(10**30)
        return {"shipments": bucket[0], "total_kg": float(value.quantize(Decimal("0.01"), ROUND_HALF_UP))}

    summary = {
        "depots": {depot: render(bucket) for depot, bucket in depot_totals.items()},
        "months": {key: render(month_totals[key]) for key in sorted(month_totals)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(summary, handle, indent=2)
        handle.write("\n")


if __name__ == "__main__":
    main()
